// @name Daily chores
// @background #f4f1ea
// @refresh 3600
// A checklist of chores that starts again every day. The chores are the
// scene's public `chores` field, one per line, so they can be changed in the
// frame's settings, or here: tap Edit to change, add or delete them.
//
// A line can say more than the chore:
//   Water the plants @mon,thu     only on Mondays and Thursdays
//   Homework check @weekdays      Monday to Friday (@weekends, @daily too)
//   Dishes #Sam                   Sam's chore: a small tag, or Sam's group
//
// What is ticked today is the private `ticks` field, kept on disk with the day
// it belongs to. The day starts at the "New day starts at" hour (4 = 04:00),
// and then the ticks go and that day's share goes into a short history.
import { parseChores, dueOn, dayKey, logicalDay, nextReset, DAY_NAMES, MONTH_NAMES, scheduleLabel } from './chores'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-[#f4f1ea] text-[#1f2a37]',
    muted: 'text-[#6b7280]',
    card: 'bg-white',
    cardDone: 'bg-[#ebe7de]',
    doneText: 'text-[#8a8f98] line-through',
    track: 'bg-[#e2ddd2]',
    fill: 'bg-[#0f766e]',
    box: 'border-[3px] border-[#b9b2a3] bg-white',
    boxOn: 'bg-[#0f766e]',
    button: 'bg-white text-[#1f2a37] active:bg-[#e2ddd2]',
    primary: 'bg-[#0f766e] text-white active:bg-[#115e59]',
    remove: 'bg-[#b42318] text-white active:bg-[#912018]',
    field: 'bg-white focus:bg-[#f0fdfa]',
    hero: 'bg-[#0f766e] text-white',
    heroMuted: 'text-[#ccfbf1]',
    section: 'text-[#6b7280]',
    // History bars: the day's share filled in the accent, today's darker.
    bar: '#d9d3c6',
    barFill: '#5eaaa3',
    barToday: '#0f766e',
    barText: '#6b7280',
    outline: 'none',
    // A person's tag, picked by their name.
    tags: [
      'bg-[#e0e7ff] text-[#3730a3]',
      'bg-[#fde8d7] text-[#9a3412]',
      'bg-[#dcfce7] text-[#166534]',
      'bg-[#fae8ff] text-[#86198f]',
      'bg-[#e0f2fe] text-[#075985]',
      'bg-[#fef3c7] text-[#92400e]',
    ],
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    cardDone: 'bg-white border-2 border-black',
    doneText: 'text-black line-through',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    box: 'border-4 border-black bg-white',
    boxOn: 'bg-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    remove: 'bg-black text-white',
    field: 'bg-white border-2 border-black',
    hero: 'bg-black text-white',
    heroMuted: 'text-white',
    section: 'text-black',
    bar: '#ffffff',
    barFill: '#000000',
    barToday: '#000000',
    barText: '#000000',
    outline: '#000000',
    tags: ['bg-white text-black border-2 border-black'],
  },
}

// Colour e-paper (Spectra's six inks): the high-contrast page with the
// accent and the tags in solid inks, as the panel shows them (dither.nim's
// measured table), so nothing is dithered into confetti.
THEMES.inks = {
  ...THEMES.high,
  fill: 'bg-[#2a5531]',
  boxOn: 'bg-[#2a5531]',
  primary: 'bg-[#2a5531] text-white',
  remove: 'bg-[#6b1119] text-white',
  hero: 'bg-[#2a5531] text-white',
  barFill: '#2a5531',
  barToday: '#2a5531',
  tags: ['bg-[#18539a] text-white', 'bg-[#6b1119] text-white', 'bg-[#2a5531] text-white', 'bg-[#c7bb00] text-black'],
}

const themeOf = (app) => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// A field's value as the settings form or the scene's state holds it.
const flag = (value, fallback) => (value === undefined || value === null || value === '' ? fallback : value === true || value === 'true')
const numberOf = (value, fallback) => {
  const n = Number(value)
  return Number.isFinite(n) ? n : fallback
}

// The ticks: { day, done: [chore keys], history: [{ d: day, n: done, t: due }] }.
function readTicks(app) {
  let ticks = app.state.ticks
  if (typeof ticks === 'string') {
    try {
      ticks = JSON.parse(ticks)
    } catch (e) {
      ticks = null
    }
  }
  if (!ticks || typeof ticks !== 'object') ticks = {}
  return {
    day: typeof ticks.day === 'string' ? ticks.day : '',
    done: Array.isArray(ticks.done) ? ticks.done : [],
    history: Array.isArray(ticks.history) ? ticks.history : [],
  }
}

const HISTORY_KEPT = 14

// A new day: what the last one got done goes into the history, and the
// ticks start empty.
function rollOver(ticks, today, chores) {
  const history = ticks.history.filter((h) => h && h.d !== ticks.day && h.d < today)
  if (ticks.day && ticks.day < today) {
    const [y, m, d] = ticks.day.split('-').map(Number)
    const due = dueOn(chores, new Date(y, m - 1, d, 12).getDay())
    const n = due.filter((c) => ticks.done.includes(c.key)).length
    history.push({ d: ticks.day, n, t: due.length })
  }
  history.sort((a, b) => (a.d < b.d ? -1 : 1))
  return { day: today, done: [], history: history.slice(-HISTORY_KEPT) }
}

// The chores in groups: by person when asked (in the order they first come
// up, then the chores for anyone), else one group.
function groupsOf(list, byPerson) {
  if (!byPerson) return [{ name: '', items: list }]
  const names = []
  for (const c of list) if (c.person && !names.some((n) => n.toLowerCase() === c.person.toLowerCase())) names.push(c.person)
  const groups = names.map((name) => ({ name, items: list.filter((c) => c.person && c.person.toLowerCase() === name.toLowerCase()) }))
  const anyone = list.filter((c) => !c.person)
  if (anyone.length) groups.push({ name: 'Anyone', items: anyone })
  return groups
}

// The chores in the order they are drawn.
const inOrder = (list, byPerson) => groupsOf(list, byPerson).flatMap((g) => g.items)

const Check = ({ size }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12l5 5L20 7" />
  </svg>
)

const Bin = ({ size }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M4 7h16M10 11v6M14 11v6M5 7l1 12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2l1-12M9 7V4h6v3" />
  </svg>
)

// What a tap on a chore changes, as signals: a tap runs only what reads them
// (its row, the count, the bar, today's bar of the history), not get().
const ticked = new Map() // a chore's key: whether it is ticked today
const tickOf = (key) => {
  if (!ticked.has(key)) ticked.set(key, signal(false))
  return ticked.get(key)
}
const doneCount = signal(0)
// What get() last worked out, which a tap changes from.
let latest = { ticks: { day: '', done: [], history: [] }, today: '', due: [] }

const saveTicks = (doneKeys) => {
  const ticks = { ...latest.ticks, day: latest.today, done: doneKeys }
  frameos.setState('ticks', ticks)
  latest = { ...latest, ticks }
}

const toggle = (key) => {
  const { ticks, due } = latest
  const doneKeys = ticks.done.includes(key) ? ticks.done.filter((k) => k !== key) : [...ticks.done.filter((k) => due.some((c) => c.key === k)), key]
  saveTicks(doneKeys)
  // All done, or no longer: the list and what is under it change, so no
  // signal is set and get() draws it all.
  const count = due.filter((c) => doneKeys.includes(c.key)).length
  if ((count === due.length) !== (doneCount.peek() === due.length)) return
  tickOf(key).value = doneKeys.includes(key)
  doneCount.value = count
}

const scaled = (z) => (n) => Math.round(n * z)

// Who does what: a tag's color picked by the name, the same every day.
const tagClass = (t, person) => {
  let h = 0
  for (let i = 0; i < person.length; i++) h = (h * 31 + person.charCodeAt(i)) >>> 0
  return t.tags[h % t.tags.length]
}
const Tag = ({ person, z, t }) => {
  const px = scaled(z)
  return (
    <span className={`shrink-0 rounded-full px-[${px(10)}px] py-[${px(2)}px] text-[${px(14)}px] font-semibold ${tagClass(t, person.toLowerCase())}`}>{person}</span>
  )
}

// A chore as a row (`person` is '' when the list is grouped by person).
const Row = memo(({ k, name, when, person, readOnly, z, t, h }) => {
  const px = scaled(z)
  const on = !readOnly && tickOf(k).value
  // Tomorrow's chores are only to read: smaller, and nothing to tap.
  return (
    <div
      className={`flex items-center gap-[${px(12)}px] h-[${h || (readOnly ? px(40) : px(54))}px] rounded-[${px(readOnly ? 10 : 14)}px] pl-[${px(readOnly ? 14 : 12)}px] pr-[${px(14)}px] ${on || readOnly ? t.cardDone : t.card}`}
      onClick={readOnly ? undefined : () => toggle(k)}
    >
      {readOnly ? null : (
        <div className={`shrink-0 w-[${px(32)}px] h-[${px(32)}px] rounded-full flex items-center justify-center text-white ${on ? t.boxOn : t.box}`}>
          {on ? <Check size={px(20)} /> : null}
        </div>
      )}
      <span className={`flex-1 min-w-0 truncate text-[${readOnly ? px(17) : px(20)}px] ${on ? t.doneText : ''}`}>{name}</span>
      {when ? <span className={`shrink-0 text-[${px(14)}px] ${t.muted}`}>{when}</span> : null}
      {person ? <Tag person={person} z={z} t={t} /> : null}
    </div>
  )
})

// A person's share ticked off, "2 of 3" (`keys`: their chores' keys, a line each).
const GroupCount = memo(({ keys }) => {
  const list = keys.split('\n')
  return <span>{`${list.filter((k) => tickOf(k).value).length} of ${list.length}`}</span>
})

const DoneCount = memo(({ total, z, t, small }) => {
  const px = scaled(z)
  return (
    <div className="shrink-0 flex flex-col items-end">
      <span className={`text-[${px(small ? 20 : 30)}px] ${small ? 'leading-tight' : ''} font-bold`}>{total ? `${doneCount.value}/${total}` : '0'}</span>
      <span className={`text-[${px(small ? 12 : 14)}px] ${small ? 'leading-tight' : ''} ${t.muted}`}>{total ? 'done today' : 'chores today'}</span>
    </div>
  )
})

const Progress = memo(({ total, h, t }) => (
  <div className={`shrink-0 h-[${h}px] rounded-full ${t.track}`}>
    <div className={`h-full rounded-full ${t.fill} w-[${Math.round((doneCount.value * 100) / total)}%]`} />
  </div>
))

// The last days as bars, today's last: how much of each day's chores got done.
const historySize = (count, z, small) => {
  const barW = Math.round((small ? 11 : 14) * z)
  const gap = Math.round((count > 7 ? (small ? 5 : 7) : small ? 9 : 12) * z)
  const barH = Math.round((small ? 22 : 30) * z)
  const textSize = Math.round(12 * z)
  return { barW, gap, barH, textSize, width: count * barW + (count - 1) * gap, height: barH + textSize + Math.round((small ? 4 : 6) * z) }
}
const History = memo(({ days, z, t, small }) => {
  const doneToday = doneCount.value
  const { barW, gap, barH, textSize, width, height } = historySize(days.length, z, small)
  const r = Math.round(4 * z)
  return (
    <svg className={`w-[${width}px] h-[${height}px]`} viewBox={`0 0 ${width} ${height}`}>
      {days.map((day, i) => {
        const x = i * (barW + gap)
        const n = day.today ? doneToday : day.n
        const share = day.t > 0 ? Math.min(1, n / day.t) : day.known ? 1 : 0
        const fillH = Math.round(barH * share)
        // A day the scene did not see (the frame was off, or the scene is
        // new) is a small dot; a day it saw is a bar filled as far as it got.
        return (
          <g>
            {day.known ? (
              <rect x={x + 1} y={1} width={barW - 2} height={barH - 2} rx={r} fill={t.bar} stroke={t.outline} strokeWidth={t.outline === 'none' ? 0 : 2} />
            ) : (
              <circle cx={x + barW / 2} cy={barH - barW / 2} r={barW / 4} fill={t.barText} />
            )}
            {fillH > 0 ? <rect x={x} y={barH - fillH} width={barW} height={fillH} rx={r} fill={day.today ? t.barToday : t.barFill} /> : null}
            <text x={x + barW / 2} y={height - 1} fontSize={textSize} textAnchor="middle" fill={t.barText} fontWeight={day.today ? 'bold' : 'normal'}>
              {day.letter}
            </text>
          </g>
        )
      })}
    </svg>
  )
})

// On a round panel today's share is a ring along the rim, filling clockwise
// from the top.
const RoundRing = memo(({ total, W, H, t }) => {
  const cx = W / 2, cy = H / 2, rr = Math.min(W, H) / 2 - 5
  const share = total ? Math.min(1, doneCount.value / total) : 0
  const high = t !== THEMES.color
  const a = share * 2 * Math.PI
  const x = (cx + rr * Math.sin(a)).toFixed(1), y = (cy - rr * Math.cos(a)).toFixed(1)
  const arc = share >= 1
    ? `M ${cx} ${cy - rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy + rr} A ${rr} ${rr} 0 1 1 ${cx} ${cy - rr}`
    : `M ${cx} ${cy - rr} A ${rr} ${rr} 0 ${share > 0.5 ? 1 : 0} 1 ${x} ${y}`
  return (
    <svg className={`absolute left-0 top-0 w-[${W}px] h-[${H}px]`} viewBox={`0 0 ${W} ${H}`} fill="none" strokeWidth={8} strokeLinecap="round">
      <circle cx={cx} cy={cy} r={rr} stroke={high ? '#ffffff' : '#e2ddd2'} />
      {share > 0 ? <path d={arc} stroke={high ? '#000000' : '#0f766e'} /> : null}
    </svg>
  )
})

const RoundCount = memo(({ total, line, z, t }) => (
  <span className={`text-[${Math.round(15 * z)}px] ${t.muted} truncate`}>
    {total ? `${line} · ${doneCount.value}/${total} done` : line}
  </span>
))

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  // Sizes are made for 800x480 (and 480x800) and grow or shrink with the canvas.
  const z = Math.max(0.85, Math.min(2.5, Math.min(W, H) / 480, Math.max(W, H) / 800))
  const px = (n) => Math.round(n * z)
  const t = themeOf(app)
  const fast = app.frame.fast ?? !app.frame.paper

  const resetHour = Math.max(0, Math.min(23, Math.floor(numberOf(app.state.resetHour, 4))))
  const groupByPerson = flag(app.state.groupByPerson, false)
  const showTomorrow = flag(app.state.showTomorrow, true)
  const historyDays = Math.max(0, Math.min(HISTORY_KEPT, Math.floor(numberOf(app.state.history, 7))))
  const title = String(app.state.title ?? '').trim() || 'Chores'
  const text = typeof app.state.chores === 'string' ? app.state.chores : ''
  const chores = parseChores(text)

  // Today, as the chores count it: before the reset hour it is still yesterday.
  const now = Date.now()
  const day = logicalDay(now, resetHour)
  const today = dayKey(day)
  let ticks = readTicks(app)
  if (ticks.day !== today) {
    ticks = rollOver(ticks, today, chores)
    frameos.setState('ticks', ticks)
  }

  // Draw again when the day starts, if that comes before the next render.
  const untilReset = Math.ceil((nextReset(now, resetHour) - now) / 1000) + 1
  const interval = numberOf(app.state.refreshInterval, 3600)
  if (untilReset < interval) frameos.setNextSleep(untilReset)

  const due = dueOn(chores, day.getDay())
  const done = due.filter((c) => ticks.done.includes(c.key))
  const allDone = due.length > 0 && done.length === due.length
  const otherDays = chores.length - due.length
  const tomorrow = new Date(day.getTime() + 86400000)
  const dueTomorrow = dueOn(chores, tomorrow.getDay())

  const editing = frameos.recall('editing') === true
  const asking = frameos.recall('asking') ?? -1
  const draft = frameos.recall('draft') || ''
  const peek = frameos.recall('peek') === true && allDone

  // The signals as the scene's state has them: a whole render may come from
  // anything (the buttons' forward and back, a new day, the settings).
  latest = { ticks, today, due }
  for (const c of due) tickOf(c.key).value = ticks.done.includes(c.key)
  doneCount.value = done.length

  const lines = text.split('\n')
  const saveLines = (next) => frameos.setState('chores', next.join('\n'))
  const add = () => {
    const line = (frameos.recall('draft') || '').trim()
    if (!line) return
    saveLines([...lines.filter((l) => l.trim() !== ''), line])
    frameos.remember('draft', '')
  }

  const portrait = H > W * 1.1
  const twoColumns = !portrait && W >= 640 * z
  const round = context?.round === true
  // A small panel (a watch, a 2.8" screen, the 4.2" and 5.79" e-paper): a
  // header of two short lines, smaller rows, and the history strip smaller,
  // beside the title on a wide strip or left out where it would take the
  // list's room.
  const compact = !round && Math.min(W, H) < 340
  const rowZ = compact ? z * 0.85 : z
  const pad = compact ? px(12) : px(20)
  const gap = compact ? px(8) : px(12)

  const List = ({ list, readOnly, rowH }) => (
    <div className={`flex flex-col gap-[${px(14)}px]`}>
      {groupsOf(list, groupByPerson).map((group) => (
        <div className={`flex flex-col gap-[${px(8)}px]`}>
          {group.name ? (
            <div className={`flex items-center gap-[${px(8)}px] text-[${px(15)}px] ${t.section}`}>
              <span className="font-bold uppercase">{group.name}</span>
              {readOnly ? null : <GroupCount keys={group.items.map((c) => c.key).join('\n')} />}
            </div>
          ) : null}
          <div className={twoColumns ? `grid grid-cols-2 gap-[${px(8)}px]` : `flex flex-col gap-[${px(8)}px]`}>
            {group.items.map((chore) => (
              <Row
                k={chore.key}
                name={chore.name}
                when={compact && W < 300 ? '' : scheduleLabel(chore.days)}
                person={groupByPerson ? '' : chore.person}
                readOnly={readOnly}
                z={rowZ}
                t={t}
                h={rowH}
              />
            ))}
          </div>
        </div>
      ))}
    </div>
  )

  const buttonH = compact ? px(36) : px(46)
  const Button = ({ label, onClick, kind }) => (
    <div
      className={`shrink-0 h-[${buttonH}px] px-[${compact ? px(12) : px(18)}px] rounded-[${px(12)}px] flex items-center justify-center text-[${compact ? px(16) : px(18)}px] font-bold ${kind === 'primary' ? t.primary : kind === 'remove' ? t.remove : t.button}`}
      onClick={onClick}
    >
      {label}
    </div>
  )

  const longDate = `${DAY_NAMES[day.getDay()]} ${day.getDate()} ${MONTH_NAMES[day.getMonth()]}`
  const shortDate = `${DAY_NAMES[day.getDay()].slice(0, 3)} ${day.getDate()} ${MONTH_NAMES[day.getMonth()].slice(0, 3)}`
  const dateLine = compact || (round && W < 420) ? shortDate : longDate
  const resetLabel = `${String(resetHour).padStart(2, '0')}:00`

  // The history: the days before today, then today as it stands.
  const historyBars = []
  for (let back = historyDays - 1; back >= 0 && historyDays > 0; back--) {
    const d = new Date(day.getTime() - back * 86400000)
    const key = dayKey(d)
    const letter = DAY_NAMES[d.getDay()].slice(0, back === 0 ? 3 : 1)
    if (back === 0) historyBars.push({ letter, n: done.length, t: due.length, known: true, today: true })
    else {
      const h = ticks.history.find((x) => x.d === key)
      historyBars.push({ letter, n: h ? h.n : 0, t: h ? h.t : 0, known: !!h, today: false })
    }
  }

  // A round panel: the title in the arc at the top, the list as wide as the
  // circle lets it be, the buttons in the arc at the bottom.
  const R = Math.min(W, H) / 2 - 12
  const chord = (dy) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const at = (top, height, child, cls = '') => {
    const far = Math.max(Math.abs(top), Math.abs(top + height))
    const w = chord(far)
    return (
      <div className={`absolute left-[${Math.round(W / 2 - w / 2)}px] top-[${Math.round(H / 2 + top)}px] w-[${w}px] h-[${height}px] ${cls}`}>{child}</div>
    )
  }
  const roundPage = (top, middle, bottom) => {
    const headTop = -Math.round(R * 0.9)
    const midTop = -Math.round(R * 0.56)
    const midBottom = Math.round(R * 0.46)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
        {editing || !due.length ? null : <RoundRing total={due.length} W={W} H={H} t={t} />}
        {at(headTop, midTop - headTop - px(6), top, 'flex flex-col items-center justify-end')}
        {at(midTop, midBottom - midTop, middle, 'flex flex-col')}
        {at(midBottom + px(10), px(48), bottom, `flex items-center justify-center gap-[${px(8)}px]`)}
      </div>
    )
  }
  const editButton = (
    <Button
      label={editing ? 'Done' : 'Edit'}
      kind={editing ? 'primary' : ''}
      onClick={() => {
        frameos.remember('editing', !editing)
        frameos.remember('asking', -1)
      }}
    />
  )
  const roundHeader = (
    <div className="flex flex-col items-center">
      <span className={`text-[${px(30)}px] font-bold truncate`}>{title}</span>
      {editing ? null : <RoundCount total={due.length} line={dateLine} z={z} t={t} />}
    </div>
  )

  // Where the history goes: under the list, beside the title on a short wide
  // strip, or nowhere on a short narrow screen.
  const historyAt = historyBars.length < 2 ? 'none' : !compact || H >= 290 ? 'footer' : W >= 560 ? 'header' : 'none'
  const history = historySize(historyBars.length, z, compact)
  // The heights of what is around the list, so the list can be sized to
  // whole rows (no row cut in half at its bottom edge).
  const headerH = compact
    ? Math.max(buttonH, Math.ceil(1.25 * (px(24) + px(13))), historyAt === 'header' ? history.height : 0)
    : Math.max(buttonH, Math.ceil(1.5 * (px(34) + px(16))))
  const header = (
    <div className={`shrink-0 flex items-center gap-[${compact ? px(10) : px(14)}px] h-[${headerH}px]`}>
      <div className="flex-1 min-w-0 flex flex-col">
        <span className={`text-[${compact ? px(24) : px(34)}px] ${compact ? 'leading-tight' : ''} font-bold truncate`}>{title}</span>
        <span className={`text-[${compact ? px(13) : px(16)}px] ${compact ? 'leading-tight' : ''} ${t.muted} truncate`}>{dateLine}</span>
      </div>
      {!editing && historyAt === 'header' ? <History days={historyBars} z={z} t={t} small /> : null}
      {editing ? null : <DoneCount total={due.length} z={z} t={t} small={compact} />}
      <Button
        label={editing ? 'Done' : 'Edit'}
        kind={editing ? 'primary' : ''}
        onClick={() => {
          frameos.remember('editing', !editing)
          frameos.remember('asking', -1)
        }}
      />
    </div>
  )

  if (editing) {
    const lineRow = (line, i) =>
      line.trim() === '' ? null : asking === i ? (
        <div className={`flex items-center gap-[${px(10)}px] rounded-[${px(14)}px] px-[${px(12)}px] py-[${px(6)}px] ${t.card}`}>
          <span className={`flex-1 min-w-0 truncate text-[${px(18)}px]`}>{`Delete "${line.trim()}"?`}</span>
          <Button label="Cancel" onClick={() => frameos.remember('asking', -1)} />
          <Button
            label="Delete"
            kind="remove"
            onClick={() => {
              saveLines(lines.filter((_, j) => j !== i))
              frameos.remember('asking', -1)
            }}
          />
        </div>
      ) : (
        <div className={`flex items-center gap-[${px(8)}px]`}>
          <input
            className={`flex-1 h-[${px(48)}px] px-[${px(14)}px] rounded-[${px(12)}px] text-[${px(18)}px] ${t.card} ${t.field}`}
            value={line}
            onChange={(e) => saveLines(lines.map((l, j) => (j === i ? e.target.value : l)))}
          />
          <div className={`shrink-0 w-[${px(46)}px] h-[${px(46)}px] flex items-center justify-center ${t.muted}`} onClick={() => frameos.remember('asking', i)}>
            <Bin size={px(24)} />
          </div>
        </div>
      )
    if (round) {
      return roundPage(
        roundHeader,
        <div className="flex-1 min-h-0 flex flex-col gap-[6px]">
          <div className="flex-1 min-h-0 overflow-y-auto">
            <div className={`flex flex-col gap-[${px(8)}px]`}>
              <span className={`text-[${px(15)}px] ${t.muted}`}>
                One chore a line. Add @mon,thu or @weekdays for the days it is due, and #Name for who does it.
              </span>
              {lines.map(lineRow)}
            </div>
          </div>
          <div className={`flex items-center gap-[${px(8)}px]`}>
            <input
              className={`flex-1 h-[${px(46)}px] px-[${px(12)}px] rounded-[${px(12)}px] text-[${px(18)}px] ${t.card} ${t.field}`}
              value={draft}
              placeholder="Add a chore"
              onChange={(e) => frameos.remember('draft', e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') add()
              }}
            />
            <Button label="Add" kind="primary" onClick={add} />
          </div>
        </div>,
        editButton,
      )
    }
    return (
      <div className={`flex flex-col w-full h-full gap-[${gap}px] p-[${pad}px] ${t.page}`}>
        {header}
        <span className={`text-[${px(15)}px] ${t.muted}`}>
          One chore a line. Add @mon,thu or @weekdays for the days it is due, and #Name for who does it.
        </span>
        <div className="flex-1 min-h-0 overflow-y-auto">
          <div className={`flex flex-col gap-[${px(8)}px]`}>
            {lines.map((line, i) =>
              line.trim() === '' ? null : asking === i ? (
                <div className={`flex items-center gap-[${px(10)}px] rounded-[${px(14)}px] px-[${px(12)}px] py-[${px(6)}px] ${t.card}`}>
                  <span className={`flex-1 min-w-0 truncate text-[${px(18)}px]`}>{`Delete "${line.trim()}"?`}</span>
                  <Button label="Cancel" onClick={() => frameos.remember('asking', -1)} />
                  <Button
                    label="Delete"
                    kind="remove"
                    onClick={() => {
                      saveLines(lines.filter((_, j) => j !== i))
                      frameos.remember('asking', -1)
                    }}
                  />
                </div>
              ) : (
                <div className={`flex items-center gap-[${px(8)}px]`}>
                  <input
                    className={`flex-1 h-[${px(48)}px] px-[${px(14)}px] rounded-[${px(12)}px] text-[${px(18)}px] ${t.card} ${t.field}`}
                    value={line}
                    onChange={(e) => saveLines(lines.map((l, j) => (j === i ? e.target.value : l)))}
                  />
                  <div className={`shrink-0 w-[${px(46)}px] h-[${px(46)}px] flex items-center justify-center ${t.muted}`} onClick={() => frameos.remember('asking', i)}>
                    <Bin size={px(24)} />
                  </div>
                </div>
              ),
            )}
          </div>
        </div>
        <div className={`flex items-center gap-[${px(10)}px]`}>
          <input
            className={`flex-1 h-[${px(48)}px] px-[${px(14)}px] rounded-[${px(12)}px] text-[${px(18)}px] ${t.card} ${t.field}`}
            value={draft}
            placeholder="Add a chore, like Feed the cat #Mia"
            onChange={(e) => frameos.remember('draft', e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') add()
            }}
          />
          <Button label="Add" kind="primary" onClick={add} />
        </div>
      </div>
    )
  }

  // Under the list: the history and two short lines (each kept to one line,
  // so the footer's height is known); a small panel keeps the strip alone.
  const footerH = compact
    ? historyAt === 'footer' ? history.height : 0
    : Math.max(historyAt === 'footer' ? history.height : 0, Math.ceil(2 * 1.5 * px(13)))
  const footer = !footerH ? null : (
    <div className={`shrink-0 flex items-end gap-[${compact ? px(10) : px(14)}px] h-[${footerH}px]`}>
      {historyAt === 'footer' ? <History days={historyBars} z={z} t={t} small={compact} /> : null}
      <div className="flex-1 min-w-0 flex flex-col">
        {compact ? (
          <span className={`text-[${px(13)}px] ${t.muted} truncate`}>{`Last ${historyBars.length} days`}</span>
        ) : (
          <>
            <span className={`text-[${px(13)}px] ${t.muted} truncate`}>
              {historyBars.length > 1 ? `Last ${historyBars.length} days · new day at ${resetLabel}` : `A new day starts at ${resetLabel}`}
            </span>
            {otherDays > 0 ? <span className={`text-[${px(13)}px] ${t.muted} truncate`}>{`${otherDays} more on other days`}</span> : null}
          </>
        )}
      </div>
    </div>
  )
  // The list's room, and its rows: as many whole rows as fit (the rest a
  // scroll away, the keys' ring bringing them in), or, where every row fits
  // with room to spare, taller rows.
  const progressH = due.length ? (compact ? px(8) : px(10)) : 0
  const parts = 2 + (progressH ? 1 : 0) + (peek ? 1 : 0) + (footerH ? 1 : 0)
  const bodyH = H - 2 * pad - headerH - progressH - (peek ? buttonH : 0) - footerH - (parts - 1) * gap
  const baseRowH = compact ? px(44) : px(54)
  const rowGap = px(8)
  const listRows = Math.ceil(due.length / (twoColumns ? 2 : 1))
  const fitRows = Math.max(1, Math.floor((bodyH + rowGap) / (baseRowH + rowGap)))
  const wholeRows = !round && !groupByPerson
  const rowH = !wholeRows || listRows > fitRows ? baseRowH : Math.min(Math.round(baseRowH * 1.5), Math.floor((bodyH - (listRows - 1) * rowGap) / Math.max(1, listRows)))
  const boxH = wholeRows && listRows > fitRows ? fitRows * baseRowH + (fitRows - 1) * rowGap : 0

  let body
  if (chores.length === 0) {
    body = (
      <div className={`flex-1 flex flex-col items-center justify-center gap-[${px(12)}px] text-center`}>
        <span className={`text-[${px(24)}px] font-bold`}>No chores yet</span>
        <span className={`text-[${px(16)}px] ${t.muted}`}>Press Edit to add some, or set them in the scene's settings.</span>
      </div>
    )
  } else if (due.length === 0) {
    body = (
      <div className={`flex-1 min-h-0 flex flex-col gap-[${px(12)}px]`}>
        <div className={`rounded-[${px(18)}px] p-[${px(18)}px] ${t.card}`}>
          <span className={`text-[${px(24)}px] font-bold`}>Nothing due today</span>
        </div>
        {showTomorrow && dueTomorrow.length ? (
          <div className="flex-1 min-h-0 overflow-y-auto">
            <div className={`flex flex-col gap-[${px(8)}px]`}>
              <span className={`text-[${px(15)}px] font-bold uppercase ${t.section}`}>{`Tomorrow, ${DAY_NAMES[tomorrow.getDay()]}`}</span>
              <List list={dueTomorrow} readOnly />
            </div>
          </div>
        ) : null}
      </div>
    )
  } else if (allDone && !peek) {
    body = (
      <div className={`flex-1 min-h-0 flex flex-col gap-[${px(12)}px]`}>
        <div className={`flex items-center gap-[${px(16)}px] rounded-[${px(18)}px] px-[${px(18)}px] py-[${px(14)}px] ${t.hero}`} onClick={() => frameos.remember('peek', true)}>
          <div className={`shrink-0 w-[${px(56)}px] h-[${px(56)}px] rounded-full flex items-center justify-center border-[${px(3)}px] border-white`}>
            <Check size={px(34)} />
          </div>
          <div className="flex-1 min-w-0 flex flex-col">
            <span className={`text-[${px(28)}px] font-bold`}>All done for today</span>
            <span className={`text-[${px(15)}px] ${t.heroMuted}`}>{`${due.length} ${due.length === 1 ? 'chore' : 'chores'} ticked off. Press to see them.`}</span>
          </div>
        </div>
        {showTomorrow && dueTomorrow.length ? (
          <div className="flex-1 min-h-0 overflow-y-auto">
            <div className={`flex flex-col gap-[${px(8)}px]`}>
              <span className={`text-[${px(15)}px] font-bold uppercase ${t.section}`}>{`Tomorrow, ${DAY_NAMES[tomorrow.getDay()]}`}</span>
              <List list={dueTomorrow} readOnly />
            </div>
          </div>
        ) : null}
      </div>
    )
  } else {
    body = boxH ? (
      <div className="flex-1 min-h-0 flex flex-col">
        <div className={`h-[${boxH}px] min-h-0 overflow-y-auto`}>
          <List list={due} readOnly={false} rowH={baseRowH} />
        </div>
      </div>
    ) : (
      <div className="flex-1 min-h-0 overflow-y-auto">
        <List list={due} readOnly={false} rowH={wholeRows ? rowH : 0} />
      </div>
    )
  }

  if (round) {
    return roundPage(
      roundHeader,
      body,
      <>
        {peek ? <Button label="Back to all done" onClick={() => frameos.remember('peek', false)} /> : historyBars.length > 1 ? <History days={historyBars} z={z} t={t} /> : null}
        {editButton}
      </>,
    )
  }

  return (
    <div className={`flex flex-col w-full h-full gap-[${gap}px] p-[${pad}px] ${t.page}`}>
      {header}
      {due.length ? <Progress total={due.length} h={progressH} t={t} /> : null}
      {body}
      {peek ? (
        <div className="flex">
          <Button label="Back to all done" onClick={() => frameos.remember('peek', false)} />
        </div>
      ) : null}
      {footer}
    </div>
  )
}

// Frames with buttons and no touch: forward ticks the next chore off, back
// takes the last tick back.
export function onEvent(app, context) {
  if (context.event !== 'forward' && context.event !== 'back') return false
  const resetHour = Math.max(0, Math.min(23, Math.floor(numberOf(app.state.resetHour, 4))))
  const chores = parseChores(typeof app.state.chores === 'string' ? app.state.chores : '')
  const day = logicalDay(Date.now(), resetHour)
  const today = dayKey(day)
  let ticks = readTicks(app)
  if (ticks.day !== today) ticks = rollOver(ticks, today, chores)
  const due = inOrder(dueOn(chores, day.getDay()), flag(app.state.groupByPerson, false))
  let doneKeys = ticks.done.filter((k) => due.some((c) => c.key === k))
  if (context.event === 'forward') {
    const next = due.find((c) => !doneKeys.includes(c.key))
    if (!next) return false
    doneKeys = [...doneKeys, next.key]
  } else {
    if (!doneKeys.length) return false
    doneKeys = doneKeys.slice(0, -1)
  }
  frameos.setState('ticks', { ...ticks, done: doneKeys })
  return true
}

