// Reading the chores field and working out days.

export const DAY_NAMES = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
export const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

// A day by its first two letters, Sunday first as Date.getDay() counts.
const DAY_PREFIXES = ['su', 'mo', 'tu', 'we', 'th', 'fr', 'sa']
const WEEKDAYS = [1, 2, 3, 4, 5]
const WEEKENDS = [0, 6]
const EVERY_DAY = [0, 1, 2, 3, 4, 5, 6]

// "@mon,thu", "@weekdays", "@weekends", "@daily": the days it names, or null
// when it names none.
function daysOf(word) {
  const lower = word.toLowerCase()
  if (lower === 'weekdays' || lower === 'weekday' || lower === 'workdays') return WEEKDAYS
  if (lower === 'weekends' || lower === 'weekend') return WEEKENDS
  if (lower === 'daily' || lower === 'everyday' || lower === 'always') return EVERY_DAY
  const days = []
  for (const part of lower.split(/[,/+]/)) {
    const day = DAY_PREFIXES.indexOf(part.trim().slice(0, 2))
    if (day < 0) return null
    if (!days.includes(day)) days.push(day)
  }
  return days.length ? days : null
}

// One chore a line: { key, name, person, days }. `days` is null for every
// day. The key is what a tick is kept under: the name and the person, so the
// same chore keeps its tick when its days change.
export function parseChores(text) {
  const chores = []
  const seen = {}
  for (const raw of String(text || '').split('\n')) {
    let days = null
    let person = ''
    const words = []
    for (const word of raw.trim().split(/\s+/)) {
      if (!word) continue
      if (word.length > 1 && word[0] === '@') {
        const named = daysOf(word.slice(1))
        if (named) {
          days = (days || []).concat(named.filter((d) => !(days || []).includes(d)))
          continue
        }
      }
      if (word.length > 1 && word[0] === '#' && !person) {
        person = word.slice(1).replace(/_/g, ' ')
        continue
      }
      words.push(word)
    }
    const name = words.join(' ')
    if (!name) continue
    let key = `${name.toLowerCase()}#${person.toLowerCase()}`
    seen[key] = (seen[key] || 0) + 1
    if (seen[key] > 1) key += `~${seen[key]}`
    chores.push({ key, name, person, days: days && days.length < 7 ? days.sort() : null })
  }
  return chores
}

export const dueOn = (chores, weekday) => chores.filter((c) => !c.days || c.days.includes(weekday))

// "Mon, Thu" for a chore that is not every day; "" when it is.
export function scheduleLabel(days) {
  if (!days) return ''
  if (days.length === 5 && WEEKDAYS.every((d) => days.includes(d))) return 'Weekdays'
  if (days.length === 2 && WEEKENDS.every((d) => days.includes(d))) return 'Weekends'
  // Monday first, as a week reads.
  return [1, 2, 3, 4, 5, 6, 0].filter((d) => days.includes(d)).map((d) => DAY_NAMES[d].slice(0, 3)).join(', ')
}

// The day the chores belong to: before the reset hour it is still the day
// before. A Date at noon of that day, in the frame's time zone.
export function logicalDay(nowMs, resetHour) {
  const shifted = new Date(nowMs - resetHour * 3600000)
  return new Date(shifted.getFullYear(), shifted.getMonth(), shifted.getDate(), 12)
}

export const dayKey = (date) =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`

// When the next day starts, in ms since the epoch.
export function nextReset(nowMs, resetHour) {
  const now = new Date(nowMs)
  const next = new Date(now.getFullYear(), now.getMonth(), now.getDate(), resetHour, 0, 0, 0)
  if (next.getTime() <= nowMs) next.setDate(next.getDate() + 1)
  return next.getTime()
}
